module dma_channel_arbiter (
  input  logic        clk,
  input  logic        rst_n,
  // 兩組周邊的 DMA 傳輸要求
  input  logic        req_ch0,   // 通道 0 請求 (優先權高)
  input  logic        req_ch1,   // 通道 1 請求 (優先權低)
  output logic        ack_ch0,   // 通道 0 答覆
  output logic        ack_ch1,   // 通道 1 答覆
  output logic [1:0]  active_ch  // 當前致能的通道 ID
);
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      ack_ch0   <= 1'b0;
      ack_ch1   <= 1'b0;
      active_ch <= 2'b00;
    end else begin
      // 固定優先級仲裁 (Fixed Priority)
      if (req_ch0) begin
        ack_ch0   <= 1'b1;
        ack_ch1   <= 1'b0;
        active_ch <= 2'b01;
      end else if (req_ch1) begin
        ack_ch0   <= 1'b0;
        ack_ch1   <= 1'b1;
        active_ch <= 2'b10;
      end else begin
        ack_ch0   <= 1'b0;
        ack_ch1   <= 1'b0;
        active_ch <= 2'b00;
      end
    end
  end
endmodule

